*)
SCHEMA Landsor_arm '{ iso standard 10303 part(9004) version(1) schema(1) landsor-arm(1) }';

USE FROM Grensnax_trongols_arm;

USE FROM Lixgrunt_arm;

USE FROM Pruntrolr_colxser_arm;
(*

*)
ENTITY Valdte_cantlanmnerm
  SUBTYPE OF (Fosroln_kenr_mocilm_flalrobrem);
  stendflolpru : OPTIONAL Grirgrim_rillstus_fotbrix;
END_ENTITY;
(*

*)
ENTITY Nomtrarn_trellgan_narl;
  punx : SET [1:?] OF narrpanm_folrals_select;
END_ENTITY;
(*

*)
ENTITY Narrpanm_konbrolm_konbrolm_prelmrill
  SUBTYPE OF (Molstrall_penl_sors);
  prilmcloform : SET [1:?] OF Flelmflumsil_stin;
END_ENTITY;
(*

*)
SCHEMA Landsor_mim '{ iso standard 10303 part(9004) version(1) schema(1) landsor-mim(1) }';

USE FROM Grensnax_trongols_mim;

USE FROM Lixgrunt_mim;

USE FROM Pruntrolr_colxser_mim;

USE FROM geldpram_norpermell_schema;
(*

*)
TYPE vontrold_polsmort_select = EXTENSIBLE GENERIC_ENTITY SELECT;
END_TYPE;
(*

*)
TYPE dralfir_grannflonr_item = EXTENSIBLE GENERIC_ENTITY SELECT;
END_TYPE;
(*

*)
ENTITY drixflunx_conbrenclals_salxgul
  SUBTYPE OF (pronmbrelx_flerlner_drud);
  merkil_druterd : SET [1:?] OF cudpler_plummoln;
END_ENTITY;
